if(typeof require==='function'){var Constants=require('./constants');var Box2D=require('./box2d');var B2DUtils=require('./b2dutils');var Weapon=require('./weapon');var Projectile=require('./projectile');var TargetChange=require('./targetchange');}var HomingMissile=Projectile.subclass().name('HomingMissile');HomingMissile.fields({currentTargetPlayerId:null});HomingMissile.methods({update:function(deltaTime){this.timeAlive+=deltaTime;var currentTimeout=new Date().getTime()-this.timeoutWindow;for(var i=0;i<this.bounces.length;++i){if(this.bounces[i]>=currentTimeout){this.bounces.splice(0,i);break;}}if(this.timeAlive>Constants.HOMING_MISSILE_ACTIVATION_TIME){if(!this.isDeadlyToOwner()){this.makeDeadlyToOwner();}var tanks=this.roundModel.getTanks();var maze=this.roundModel.getMaze();if(maze){var shortestDistance=null;var targetPosition=null;var targetPlayerId=null;var startPosition={x:Math.floor(this.x/Constants.MAZE_TILE_SIZE.m),y:Math.floor(this.y/Constants.MAZE_TILE_SIZE.m)};var distances=maze.getDistancesFromPosition(startPosition);if(distances!==false){for(var tank in tanks){var endPosition={x:Math.floor(tanks[tank].getX()/Constants.MAZE_TILE_SIZE.m),y:Math.floor(tanks[tank].getY()/Constants.MAZE_TILE_SIZE.m)};var currentDistance=maze.getDistanceToPosition(distances,endPosition);if(currentDistance!==false){if(shortestDistance===null||currentDistance<shortestDistance||(currentDistance===shortestDistance&&tank!==this.getPlayerId())){shortestDistance=currentDistance;targetPosition=endPosition;targetPlayerId=tank;}}}}if(targetPlayerId){if(shortestDistance<=1){targetPosition.x=tanks[targetPlayerId].getX();targetPosition.y=tanks[targetPlayerId].getY();}else{var shortestPath=maze.getShortestPathWithGraph(startPosition,targetPosition);targetPosition.x=(shortestPath[0].x+0.5)*Constants.MAZE_TILE_SIZE.m;targetPosition.y=(shortestPath[0].y+0.5)*Constants.MAZE_TILE_SIZE.m;}var relativeToMissile=B2DUtils.toLocalSpace(this.b2dbody,targetPosition);var newSpeedX=this.b2dbody.GetLinearVelocity().x;var newSpeedY=this.b2dbody.GetLinearVelocity().y;if(relativeToMissile.x<0){newSpeedX-=Constants.HOMING_MISSILE.ACCELERATION*deltaTime;}else{newSpeedX+=Constants.HOMING_MISSILE.ACCELERATION*deltaTime;}if(relativeToMissile.y<0){newSpeedY-=Constants.HOMING_MISSILE.ACCELERATION*deltaTime;}else{newSpeedY+=Constants.HOMING_MISSILE.ACCELERATION*deltaTime;}this.b2dbody.SetLinearVelocity(Box2D.Common.Math.b2Vec2.Make(newSpeedX,newSpeedY));}if(targetPlayerId!==this.currentTargetPlayerId){var targetChange=TargetChange.create(this.id,targetPlayerId);this._emitEvent(Weapon._EVENTS.HOMING_MISSILE_TARGET_CHANGED,targetChange);}this.currentTargetPlayerId=targetPlayerId;}}if(this.b2dbody.GetLinearVelocity().LengthSquared()-this.initialSpeedSquared>0.01){var velocity=this.b2dbody.GetLinearVelocity();var length=velocity.Length();velocity.Multiply(this.initialSpeed/length);}this.x=this.b2dbody.GetPosition().x;this.y=this.b2dbody.GetPosition().y;this.speedX=this.b2dbody.GetLinearVelocity().x;this.speedY=this.b2dbody.GetLinearVelocity().y;}});if(typeof module==='object'){module.exports=HomingMissile;}